INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:hermes:cli-surface-v1','project_tool','seed://hermes/cli-surface','Hermes command surface','Snapshot date: 2026-07-15. Commands and tools: hermes chat, acp, agent, auth, backup, bundles, check, claw, completion, computer_use, config, cron, curator, dashboard, debug, desktop, doctor, dump, fallback, gateway, gui, hooks, import, insights, kanban, login, logout, logs, lsp, mcp, memory, migrate, model, pairing, plugins, portal, postinstall, profile, prompt_size, proxy, secrets, security, send, sessions, setup, skills, slack, status, tools, uninstall, update, version, webhook, whatsapp, whatsapp_cloud. Configuration model: ~/.hermes/mcp.json and Hermes profile/config directories. Source: .simplicio/hermes-command-audit/command-inventory.json.','.simplicio/hermes-command-audit/command-inventory.json','fd9dd2511ee68d8901876b20ca763ce2d9289295079b9c90889f4ea544d587c6','hermes,cli,command-surface,provenance',2.2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:hermes:config-model-v1','project_doc','seed://hermes/config-model','Hermes command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: ~/.hermes/mcp.json and Hermes profile/config directories. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: .simplicio/hermes-command-audit/command-inventory.json.','.simplicio/hermes-command-audit/command-inventory.json','8176f0a486a62776ce11e897935d88a4cafb3ff27e0607758b0ca0645db754f6','hermes,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:hermes:integration-points-v1','project_doc','seed://hermes/integration','Hermes command surface Simplicio integration points','Snapshot date: 2026-07-15. T2 MCP plus rules; audit inventory is the snapshot source and must remain provenance-linked. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: .simplicio/hermes-command-audit/command-inventory.json.','.simplicio/hermes-command-audit/command-inventory.json','51330d91437b53e2c1e73dc17f6b520a98489a698262ede1a0219788aa290ad7','hermes,simplicio,integration,governance',2);
